pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract RevertingReceiver {
    receive() external payable { revert("no"); }
    function withdrawAll(address c) public {
        C(c).withdrawAll();
    }
}

contract InvMutTest is Test {
    C c;
    RevertingReceiver receiver;
    function setUp() public { c = new C(); receiver = new RevertingReceiver(); }
    function testRegression_property() public {
        // Fund the receiver
        vm.deal(address(receiver), 5 ether);
        // Receiver deposits 2 ether
        vm.prank(address(receiver));
        c.deposit{value: 2 ether}();
        // Someone else deposits 1 ether so balance > receiver's credit
        vm.deal(address(0x123), 5 ether);
        vm.prank(address(0x123));
        c.deposit{value: 1 ether}();

        uint preBalance = address(c).balance;
        // Receiver tries to withdrawAll – will revert at sending, but order of updates differs
        bool ok;
        try receiver.withdrawAll(address(c)) { ok = true; } catch { ok = false; }
        // In reference: credit set to 0, then balance -= oCredit = balance-2, then send reverts, balance remains 3
        // In modified: credit set to 0, then balance -= oCredit = balance-2, send reverts, balance is 1
        // So reference: address(c).balance = 3; modified: address(c).balance = 1
        assertEq(address(c).balance, preBalance); // Reference: unchanged (3), modified: changed to 1
    }
}

