pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1111);
        address bob = address(0x2222);
        address attacker = address(0x3333);
        vm.deal(alice, 10 ether);
        vm.deal(bob, 10 ether);
        // Deploy a malicious contract that re-enters withdrawAll()
        MaliciousReenter mal = new MaliciousReenter(address(c));
        vm.deal(address(mal), 10 ether);

        // Step 1: Alice deposits 1 ether
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        // Step 2: Attacker (mal) deposits 1 ether
        vm.prank(address(mal));
        c.deposit{value: 1 ether}();

        // Step 3: Bob deposits 1 ether
        vm.prank(bob);
        c.deposit{value: 1 ether}();

        // Step 4: Malicious contract calls withdrawAll (will re-enter)
        vm.prank(address(mal));
        (bool ok, ) = address(mal).call(abi.encodeWithSelector(MaliciousReenter.attack.selector));
        require(ok, "attack call failed");

        // Check final balances: reference version: mal gets exactly 1 ether, balance = 0
        // Bug version: after re-entrancy, mal gets more and balance becomes negative
        // We can observe that in the reference version, calling withdrawAll from bob works fine
        // but in bug version, balance underflows causing revert or extra ether
        // Simple observation: after all calls, the total ether in contract should be 0 (all withdrawn)
        assertEq(address(c).balance, 0);
    }
}

contract MaliciousReenter {
    C target;
    constructor(address target_) { target = C(target_); }
    function attack() external {
        target.withdrawAll();
        // Re-enter if possible
        target.withdrawAll();
    }
    receive() external payable { }
}

